-- Chat v1. All objects live in the selected game schema; only Cosmic runs DDL.
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
CREATE COLLATION IF NOT EXISTS chat_unicode (provider=icu,locale='und',deterministic=true);
CREATE TABLE IF NOT EXISTS chat_schema_state(id smallint PRIMARY KEY CHECK(id=1),version integer NOT NULL,applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS chat_company_access_fences(company_id bigint PRIMARY KEY,revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
INSERT INTO chat_company_access_fences(company_id) SELECT id FROM companies ON CONFLICT DO NOTHING;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS chat_deleting boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS chat_channels(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN('global','planet','sector','corporation','private')),surface_id bigint,sector_number integer,company_id bigint,conversation_id uuid,next_seq bigint NOT NULL DEFAULT 0 CHECK(next_seq>=0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK((kind='global' AND num_nonnulls(surface_id,sector_number,company_id,conversation_id)=0) OR (kind='planet' AND surface_id IS NOT NULL AND num_nonnulls(sector_number,company_id,conversation_id)=0) OR (kind='sector' AND surface_id IS NOT NULL AND sector_number IS NOT NULL AND num_nonnulls(company_id,conversation_id)=0) OR (kind='corporation' AND company_id IS NOT NULL AND num_nonnulls(surface_id,sector_number,conversation_id)=0) OR (kind='private' AND conversation_id IS NOT NULL AND num_nonnulls(surface_id,sector_number,company_id)=0)));
CREATE UNIQUE INDEX IF NOT EXISTS chat_channel_global ON chat_channels(kind) WHERE kind='global';
CREATE UNIQUE INDEX IF NOT EXISTS chat_channel_planet ON chat_channels(surface_id) WHERE kind='planet';
CREATE UNIQUE INDEX IF NOT EXISTS chat_channel_sector ON chat_channels(surface_id,sector_number) WHERE kind='sector';
CREATE UNIQUE INDEX IF NOT EXISTS chat_channel_corporation ON chat_channels(company_id) WHERE kind='corporation';
CREATE UNIQUE INDEX IF NOT EXISTS chat_channel_private ON chat_channels(conversation_id) WHERE kind='private';
CREATE TABLE IF NOT EXISTS chat_conversations(id uuid PRIMARY KEY,type text NOT NULL CHECK(type IN('dm','group')),state text NOT NULL CHECK(state IN('pending','active','deleting')),owner_id bigint NOT NULL,title text NOT NULL DEFAULT '' CHECK(char_length(title)<=100),revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),activated_at timestamptz,delete_started_at timestamptz);
CREATE TABLE IF NOT EXISTS chat_dm_pair_locks(low_user_id bigint,high_user_id bigint,CHECK(low_user_id<high_user_id),PRIMARY KEY(low_user_id,high_user_id));
CREATE TABLE IF NOT EXISTS chat_dm_pairs(low_user_id bigint,high_user_id bigint,conversation_id uuid UNIQUE NOT NULL,CHECK(low_user_id<high_user_id),PRIMARY KEY(low_user_id,high_user_id));
CREATE TABLE IF NOT EXISTS chat_members(conversation_id uuid,user_id bigint,status text NOT NULL CHECK(status IN('active','left','kicked')),joined_at timestamptz NOT NULL DEFAULT clock_timestamp(),left_at timestamptz,join_floor_seq bigint NOT NULL DEFAULT 0,unread_count bigint NOT NULL DEFAULT 0 CHECK(unread_count>=0),PRIMARY KEY(conversation_id,user_id));
CREATE INDEX IF NOT EXISTS chat_members_user ON chat_members(user_id,status,conversation_id);
CREATE TABLE IF NOT EXISTS chat_invites(id uuid PRIMARY KEY,conversation_id uuid NOT NULL,sender_id bigint NOT NULL,recipient_id bigint NOT NULL,status text NOT NULL CHECK(status IN('pending','accepted','rejected','expired','cancelled')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,decided_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS chat_invite_pending ON chat_invites(conversation_id,recipient_id) WHERE status='pending';
CREATE INDEX IF NOT EXISTS chat_invite_recipient ON chat_invites(recipient_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS chat_invite_expiry ON chat_invites(expires_at) WHERE status='pending';
CREATE TABLE IF NOT EXISTS chat_invite_rate_locks(sender_id bigint,recipient_id bigint,PRIMARY KEY(sender_id,recipient_id));
CREATE TABLE IF NOT EXISTS chat_invite_attempts(id uuid PRIMARY KEY,sender_id bigint NOT NULL,recipient_id bigint NOT NULL,conversation_id uuid,dm_low_id bigint,dm_high_id bigint,attempted_at timestamptz NOT NULL DEFAULT clock_timestamp(),status text NOT NULL,rejected_at timestamptz);
CREATE INDEX IF NOT EXISTS chat_invite_attempt_window ON chat_invite_attempts(sender_id,recipient_id,attempted_at DESC);
CREATE INDEX IF NOT EXISTS chat_invite_dm_cooldown ON chat_invite_attempts(dm_low_id,dm_high_id,rejected_at DESC);
CREATE INDEX IF NOT EXISTS chat_invite_group_cooldown ON chat_invite_attempts(conversation_id,recipient_id,rejected_at DESC);
CREATE TABLE IF NOT EXISTS chat_message_locator(id uuid PRIMARY KEY,kind text NOT NULL,sent_at timestamptz NOT NULL,channel_id uuid NOT NULL,seq bigint NOT NULL,author_id bigint,expires_at timestamptz NOT NULL,UNIQUE(channel_id,seq));
CREATE INDEX IF NOT EXISTS chat_locator_expiry ON chat_message_locator(expires_at,id);
CREATE TABLE IF NOT EXISTS chat_messages(kind text NOT NULL,sent_at timestamptz NOT NULL,id uuid NOT NULL,expires_at timestamptz NOT NULL,channel_id uuid NOT NULL,seq bigint NOT NULL,author_id bigint,origin_sector_number integer,body text NOT NULL,reply_to_id uuid,message_type text NOT NULL DEFAULT 'user' CHECK(message_type IN('user','system')),entities jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(entities)='array'),system_code text,system_data jsonb,PRIMARY KEY(kind,sent_at,id),CHECK(char_length(body)<=CASE WHEN kind='private' THEN 500 ELSE 256 END),CHECK(expires_at>sent_at)) PARTITION BY LIST(kind);
CREATE TABLE IF NOT EXISTS chat_messages_global PARTITION OF chat_messages FOR VALUES IN('global') PARTITION BY RANGE(sent_at);
CREATE TABLE IF NOT EXISTS chat_messages_planet PARTITION OF chat_messages FOR VALUES IN('planet') PARTITION BY RANGE(sent_at);
CREATE TABLE IF NOT EXISTS chat_messages_sector PARTITION OF chat_messages FOR VALUES IN('sector') PARTITION BY RANGE(sent_at);
CREATE TABLE IF NOT EXISTS chat_messages_corporation PARTITION OF chat_messages FOR VALUES IN('corporation') PARTITION BY RANGE(sent_at);
CREATE TABLE IF NOT EXISTS chat_messages_private PARTITION OF chat_messages FOR VALUES IN('private') PARTITION BY RANGE(sent_at);
CREATE INDEX IF NOT EXISTS chat_messages_channel_seq ON chat_messages(channel_id,seq DESC);
CREATE INDEX IF NOT EXISTS chat_messages_expiry ON chat_messages(expires_at,id);

CREATE TABLE IF NOT EXISTS chat_read_receipts(user_id bigint,message_id uuid REFERENCES chat_message_locator(id) ON DELETE CASCADE,read_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(user_id,message_id));
CREATE INDEX IF NOT EXISTS chat_receipt_message ON chat_read_receipts(message_id,read_at);
CREATE TABLE IF NOT EXISTS chat_read_marks(user_id bigint,channel_id uuid,last_seen_seq bigint NOT NULL DEFAULT 0,PRIMARY KEY(user_id,channel_id));
CREATE TABLE IF NOT EXISTS chat_rate_state(user_id bigint,kind text,last_sent_at timestamptz NOT NULL DEFAULT '-infinity',PRIMARY KEY(user_id,kind));
CREATE TABLE IF NOT EXISTS chat_rate_events(user_id bigint,operation_id uuid,kind text NOT NULL CHECK(kind IN('private','report')),sent_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(user_id,operation_id));
CREATE INDEX IF NOT EXISTS chat_rate_window ON chat_rate_events(user_id,kind,sent_at DESC);
CREATE TABLE IF NOT EXISTS chat_folders(id uuid PRIMARY KEY,owner_id bigint NOT NULL,name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 100),position integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX IF NOT EXISTS chat_folder_name ON chat_folders(owner_id,lower(name COLLATE chat_unicode));
CREATE TABLE IF NOT EXISTS chat_saved_items(id uuid PRIMARY KEY,owner_id bigint NOT NULL,folder_id uuid,kind text NOT NULL CHECK(kind IN('note','copy')),body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2500),author_id bigint,author_name_snapshot text,original_at timestamptz,source_kind text,source_message_id uuid,source_channel_id uuid,surface_id bigint,sector_number integer,saved_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS chat_saved_owner ON chat_saved_items(owner_id,saved_at DESC,id);
CREATE INDEX IF NOT EXISTS chat_saved_folder ON chat_saved_items(owner_id,folder_id,saved_at DESC);
CREATE INDEX IF NOT EXISTS chat_saved_source ON chat_saved_items(source_message_id) WHERE source_message_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS chat_user_settings(user_id bigint PRIMARY KEY,settings jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS chat_notifications(id uuid PRIMARY KEY,user_id bigint NOT NULL,type text NOT NULL,ref_id uuid NOT NULL,channel_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),seen_at timestamptz,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '720 hours',UNIQUE(user_id,type,ref_id));
CREATE INDEX IF NOT EXISTS chat_notification_inbox ON chat_notifications(user_id,seen_at,created_at DESC);
CREATE TABLE IF NOT EXISTS chat_reports(id uuid PRIMARY KEY,reporter_id bigint NOT NULL,message_id uuid NOT NULL,channel_id uuid NOT NULL,kind text NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','in_review','resolved','rejected')),reviewer_id bigint,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),resolved_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS chat_report_open ON chat_reports(reporter_id,message_id) WHERE state IN('open','in_review');
CREATE INDEX IF NOT EXISTS chat_report_queue ON chat_reports(state,created_at);
CREATE TABLE IF NOT EXISTS chat_audit(id bigserial PRIMARY KEY,actor_id bigint,subject_id bigint,company_id bigint,action text NOT NULL,reason text,reference_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS chat_audit_time ON chat_audit(created_at);
CREATE TABLE IF NOT EXISTS chat_corporation_mutes(id uuid PRIMARY KEY,company_id bigint NOT NULL,user_id bigint NOT NULL,actor_id bigint NOT NULL,duration_sec integer NOT NULL CHECK(duration_sec IN(300,1800,3600,86400,604800)),reason text NOT NULL,starts_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,lifted_at timestamptz);
CREATE TABLE IF NOT EXISTS chat_corporation_mute_state(company_id bigint,user_id bigint,current_mute_id uuid,expires_at timestamptz NOT NULL DEFAULT '-infinity',changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(company_id,user_id));
CREATE TABLE IF NOT EXISTS chat_operations(user_id bigint,request_id uuid,action text NOT NULL,payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32),state text NOT NULL CHECK(state IN('in_progress','completed')),result_code text,result_json jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '4488 hours',PRIMARY KEY(user_id,request_id));
CREATE INDEX IF NOT EXISTS chat_operation_expiry ON chat_operations(expires_at);
CREATE TABLE IF NOT EXISTS chat_outbox(id bigserial PRIMARY KEY,event_kind text NOT NULL,channel_id uuid,target_user_id bigint,reference_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),processed_at timestamptz);
CREATE INDEX IF NOT EXISTS chat_outbox_pending ON chat_outbox(id) WHERE processed_at IS NULL;
CREATE TABLE IF NOT EXISTS chat_ws_leases(user_id bigint PRIMARY KEY,connection_id uuid NOT NULL,server_instance uuid NOT NULL,generation bigint NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL,renewed_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS chat_company_deletion_requests(company_id bigint PRIMARY KEY,operation_id uuid UNIQUE NOT NULL,initiated_at timestamptz NOT NULL DEFAULT clock_timestamp(),state text NOT NULL DEFAULT 'deleting');
CREATE TABLE IF NOT EXISTS chat_company_cleanup_receipts(company_id bigint PRIMARY KEY,operation_id uuid UNIQUE NOT NULL,cleaned_at timestamptz NOT NULL DEFAULT clock_timestamp(),channel_deleted boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS chat_surface_cleanup_requests(surface_id bigint PRIMARY KEY,operation_id uuid UNIQUE NOT NULL,initiated_at timestamptz NOT NULL DEFAULT clock_timestamp(),state text NOT NULL DEFAULT 'retiring');
CREATE TABLE IF NOT EXISTS chat_surface_cleanup_receipts(surface_id bigint PRIMARY KEY,operation_id uuid UNIQUE NOT NULL,cleaned_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS chat_game_moderator_grants(user_id bigint PRIMARY KEY,granted_by bigint NOT NULL,granted_at timestamptz NOT NULL DEFAULT clock_timestamp(),revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS chat_cleanup_jobs(id uuid PRIMARY KEY,kind text NOT NULL,scope_id text NOT NULL,operation_id uuid NOT NULL,phase text NOT NULL DEFAULT 'queued',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),last_cursor bigint,error_code text,UNIQUE(kind,scope_id,operation_id));
INSERT INTO chat_schema_state(id,version) VALUES(1,1) ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS chat_recovery_state(id smallint PRIMARY KEY CHECK(id=1),installation_id uuid NOT NULL DEFAULT gen_random_uuid(),erasure_count bigint NOT NULL DEFAULT 0 CHECK(erasure_count>=0));
INSERT INTO chat_recovery_state(id) VALUES(1) ON CONFLICT DO NOTHING;

CREATE INDEX IF NOT EXISTS chat_outbox_recent ON chat_outbox(created_at,id);
CREATE INDEX IF NOT EXISTS chat_messages_id ON chat_messages(id);
